mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.8, -3.0);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.25) * rd.yz;
  vec3 col = vec3(0.01, 0.01, 0.02);
  vec3 pos = ro;
  float diskGlow = 0.0;
  for (int i = 0; i < 48; i++) {
    float r = length(pos);
    if (r < 0.6) { col = vec3(0.0); break; }
    // Gravitational bend towards black hole
    vec3 force = -normalize(pos) / (r * r * 0.8);
    rd = normalize(rd + force * 0.08);
    pos += rd * 0.12;
    // Accretion disk plane around y = 0
    if (abs(pos.y) < 0.15 && r > 0.8 && r < 2.5) {
      float dens = (1.0 - abs(pos.y) / 0.15) * (1.0 - (r - 0.8) / 1.7);
      float swirl = sin(atan(pos.z, pos.x) * 4.0 - r * 8.0 + time * 4.0);
      diskGlow += dens * (0.8 + 0.4 * swirl) * 0.2;
    }
  }
  col += diskGlow * vec3(1.2, 0.5, 0.1) * (1.0 + bass);
  ret = col;
}
